<script setup>
import { computed,onMounted,ref } from 'vue';import { statistics } from '../../api/admin';import { session } from '../../utils/session';import { text } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue'
const data=ref({});const role=session.user.role;const statusRows=computed(()=>data.value.casesByStatus||[]);const typeRows=computed(()=>data.value.casesByType||[]);onMounted(async()=>data.value=(await statistics(role)).data)
</script>
<template><div class="page"><PageHeader :title="role==='ADMIN'?'业务统计':'个人业绩'" description="基于数据库聚合的实时业务数据"/><section class="metric-grid"><article class="metric-card"><span>案件总数</span><strong class="metric-value">{{data.cases||0}}</strong></article><article class="metric-card"><span>办理中</span><strong class="metric-value">{{data.processingCases||0}}</strong></article><article class="metric-card"><span>未完成时限</span><strong class="metric-value">{{data.pendingDeadlines||0}}</strong></article><article class="metric-card"><span>本月结案</span><strong class="metric-value">{{data.monthlyCompletedCases||0}}</strong></article></section><div class="split-panels"><section class="section-panel"><div class="section-title"><h2>案件状态分布</h2></div><el-table :data="statusRows"><el-table-column label="状态"><template #default="{row}">{{text('caseStatus',row.status)}}</template></el-table-column><el-table-column prop="total" label="数量"/></el-table></section><section class="section-panel"><div class="section-title"><h2>案件类型分布</h2></div><el-table :data="typeRows"><el-table-column label="类型"><template #default="{row}">{{text('caseType',row.caseType)}}</template></el-table-column><el-table-column prop="total" label="数量"/></el-table></section></div></div></template>
